// Placeholder for Dropzone.js. Replace with official build for production.
// https://www.dropzone.dev/
(function(){
  if (window.Dropzone) return;
  function DZ(element, options){
    this.element = typeof element === 'string' ? document.querySelector(element) : element;
    this.options = options || {};
    this.files = [];
    this._init();
  }
  DZ.prototype._init = function(){
    var el = this.element;
    el.classList.add('dropzone');
    el.addEventListener('dragover', function(e){e.preventDefault();});
    el.addEventListener('drop', function(e){e.preventDefault();});
  };
  DZ.prototype.processQueue = function(){ console.warn('Dropzone stub: no upload performed.'); };
  DZ.prototype.on = function(){ };
  DZ.confirm = function(msg, ok, cancel){ if(confirm(msg)) ok(); else if(cancel) cancel(); };
  window.Dropzone = DZ;
})();
